insert into public.franchise_territory_versions(id,franchise_id,version,territory_code,name_fr,name_ar,scope_snapshot,effective_from,effective_until,content_hash,created_by,created_at)values('a3624100-0000-4000-8000-000000000001','a3624000-0000-4000-8000-000000000001',1,'TEST362_TERRITORY','Territoire TEST362','نطاق اختبار362','{}','2026-09-10T00:00:00Z','2027-09-10T00:00:00Z',private.canonical_request_hash('{"TEST_ONLY":"INITIAL_HISTORICAL_TERRITORY"}'::jsonb),'a3620000-0000-4000-8000-000000000001','2026-09-10T00:00:00Z');
