insert into public.franchise_activation_evidence(invitation_id,franchise_id,approved_mandate_version_id,active_mandate_version_id,mandate_hash,activation_mode,environment,actor_user_id,evidence_snapshot,evidence_hash,recorded_at)
select'a3624400-0000-4000-8000-000000000001','a3624000-0000-4000-8000-000000000001','a3624200-0000-4000-8000-000000000001','a3624200-0000-4000-8000-000000000002',(select content_hash from public.franchise_mandate_versions where id='a3624200-0000-4000-8000-000000000001'),'NON_CONTRACTUAL_DEMO','DEVELOPMENT','a3620000-0000-4000-8000-000000000003',snapshot,private.canonical_request_hash(snapshot),'2026-09-11T00:00:00Z'
from(select jsonb_build_object('invitationId','a3624400-0000-4000-8000-000000000001','franchiseId','a3624000-0000-4000-8000-000000000001','operatorOrganizationId','a3621000-0000-4000-8000-000000000001','approvalRequestId','a3624300-0000-4000-8000-000000000001','approvedMandateVersionId','a3624200-0000-4000-8000-000000000001','activeMandateVersionId','a3624200-0000-4000-8000-000000000002','mandateHash',(select content_hash from public.franchise_mandate_versions where id='a3624200-0000-4000-8000-000000000001'),'activationMode','NON_CONTRACTUAL_DEMO','environment','DEVELOPMENT','actorUserId','a3620000-0000-4000-8000-000000000003','legalProof',null,'nonContractualDemo',true,'TEST_ONLY','INITIAL_HISTORICAL_MASTER_METADATA')snapshot)initial;
insert into finance362 select 'basis',jsonb_build_object('franchise_id',franchise_id,'approved_id',id,'hash',content_hash)from public.franchise_mandate_versions where id='a3624200-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into finance362 select 'book',public.open_franchise_pnl_book_for_mandate_v1((v->>'franchise_id')::uuid,(v->>'approved_id')::uuid,v->>'hash','MAD',(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),'TEST362-open-book')from finance362 where k='basis';
-- The amounts below are TEST journal facts, not a fiscal rate or commercial price.
insert into finance362 values('expense',jsonb_build_object('id',public.post_financial_journal('a3621000-0000-4000-8000-000000000001','TEST362-expense',null,'TEST_FRANCHISE_EXPENSE','MAD','2026-10-15T12:00:00Z','TEST native expense and independently stated tax','[{"account_id":"a3623000-0000-4000-8000-000000000002","direction":"DEBIT","amount_minor":100},{"account_id":"a3623000-0000-4000-8000-000000000003","direction":"DEBIT","amount_minor":20},{"account_id":"a3623000-0000-4000-8000-000000000001","direction":"CREDIT","amount_minor":120}]')));
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','DIRECT_MARKETING_COST',100,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST independent expense review',null,'TEST362-self-expense')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'42501','FRANCHISE_INDEPENDENT_REVIEW_REQUIRED','journal poster cannot independently classify its own expense');
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','DIRECT_MARKETING_COST',120,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST gross amount must be rejected',null,'TEST362-tax-as-cost')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'23514','FRANCHISE_PNL_NET_AMOUNT_MISMATCH','tax asset amount is not silently treated as expense');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'REVENUE','COLLECTED_NET_REVENUE',100,%L,'ARBITRARY_RECEIPT','invented','2026-10-15','TEST generic journal is not native revenue',null,'TEST362-unproved-income')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense')),'55000','FRANCHISE_NATIVE_REVENUE_RECONCILIATION_REQUIRED','generic posted journal never proves collected net revenue');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','DIRECT_MARKETING_COST',100,%L,'FINANCIAL_JOURNAL','wrong-source','2026-10-15','TEST wrong source must be rejected',null,'TEST362-wrong-source')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense')),'23514','FRANCHISE_PNL_SOURCE_MISMATCH','exact source object is bound to the actual immutable journal');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','APPROVED_SHARED_CENTRAL_COST',100,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST generic shared cost label is not contractual approval',null,'TEST362-unapproved-shared-cost')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'55000','FRANCHISE_SHARED_CENTRAL_COST_POLICY_REQUIRED','shared central cost remains excluded despite a valid net expense journal and independent reviewer');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','COLLECTED_NET_REVENUE',100,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST cost cannot be classified as collected revenue',null,'TEST362-invalid-category')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'22023','FRANCHISE_PNL_CATEGORY_EFFECT_MISMATCH','cost and revenue categories cannot be interchanged');
insert into finance362 select 'cost',public.post_franchise_pnl_entry((select(v->>'book_id')::uuid from finance362 where k='book'),'COST','DIRECT_MARKETING_COST',100,(v->>'id')::uuid,'FINANCIAL_JOURNAL',v->>'id','2026-10-15','TEST independent expense review',null,'TEST362-approved-expense')from finance362 where k='expense';
select is(public.post_franchise_pnl_entry((select(v->>'book_id')::uuid from finance362 where k='book'),'COST','DIRECT_MARKETING_COST',100,(select(v->>'id')::uuid from finance362 where k='expense'),'FINANCIAL_JOURNAL',(select v->>'id'from finance362 where k='expense'),'2026-10-15','TEST independent expense review',null,'TEST362-approved-expense'),(select v from finance362 where k='cost'),'expense retry returns its exact committed receipt');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','DIRECT_MARKETING_COST',100,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST same journal under a different key',null,'TEST362-duplicate-expense')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'23514','FRANCHISE_PNL_JOURNAL_ALREADY_USED','a new idempotency key cannot duplicate the expense');
insert into finance362 values('cutoff',jsonb_build_object('at',clock_timestamp()));
insert into finance362 select 'close',public.close_franchise_profit_period((v->>'book_id')::uuid,'2026-10-01','2026-10-31',(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select(v->>'at')::timestamptz from finance362 where k='cutoff'),'TEST October actual expense reconciliation','TEST362-close')from finance362 where k='book';
select is((select v->>'gross_revenue_ex_tax_minor'from finance362 where k='close'),'0','no collected revenue was invented');
select is((select v->>'costs_and_refunds_minor'from finance362 where k='close'),'100','closure includes the actual net expense recorded before its frozen cutoff');
select is((select v->>'distributable_profit_minor'from finance362 where k='close'),'-100','actual expense produces a loss, never a fictitious distributable profit');
select is(public.close_franchise_profit_period((select(v->>'book_id')::uuid from finance362 where k='book'),'2026-10-01','2026-10-31',(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select(v->>'at')::timestamptz from finance362 where k='cutoff'),'TEST October actual expense reconciliation','TEST362-close'),(select v from finance362 where k='close'),'clôture retry retains the same version and exact response');
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-01','2026-10-31',%L,%L,'TEST changed reason conflicts with committed request','TEST362-close')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select v->>'at'from finance362 where k='cutoff')),'22000','IDEMPOTENCY_PAYLOAD_MISMATCH','reusing a close key with changed intent is rejected');
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-01','2026-10-31',%L,'2026-10-30T00:00:00+01:00','TEST cannot certify an unfinished cutoff','TEST362-early-cutoff')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1)),'22023','INVALID_FRANCHISE_CLOSURE','cutoff must include the whole claimed civil period');
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-15','2026-10-31',%L,%L,'TEST overlapping interval must not accrue a second time','TEST362-overlap')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select v->>'at'from finance362 where k='cutoff')),'23514','FRANCHISE_OVERLAPPING_PERIOD_REVIEW_REQUIRED','a second overlapping period cannot classify or allocate the same ledger history');
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-01','2026-10-31',%L,(select(v->>'at')::timestamptz from finance362 where k='cutoff'),'TEST October actual expense reconciliation','TEST362-close')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select v->>'at'from finance362 where k='cutoff')),'42501','FRANCHISE_CLOSE_DENIED','even successful receipts cannot be replayed without required AAL2');
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-01','2026-10-31',%L,%L,'TEST October actual expense reconciliation','TEST362-close')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select v->>'at'from finance362 where k='cutoff')),'42501','FRANCHISE_CLOSE_DENIED','missing AAL is never treated as permission to replay a financial close');
select throws_ok(format($q$select public.post_franchise_pnl_entry(%L,'COST','DIRECT_MARKETING_COST',100,%L,'FINANCIAL_JOURNAL',%L,'2026-10-15','TEST independent expense review',null,'TEST362-approved-expense')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),(select v->>'id'from finance362 where k='expense')),'42501','FRANCHISE_PNL_POST_DENIED','missing AAL cannot replay a classified expense');
select throws_ok(format($q$select public.record_franchise_distribution_payout(%L,'FRANCHISEE',1,%L,'TEST payout missing MFA',%L,'TEST362-payout-missing-aal')$q$,(select v->>'book_id'from finance362 where k='book'),(select v->>'id'from finance362 where k='expense'),repeat('a',64)),'42501','FRANCHISE_PAYOUT_DENIED','missing AAL is denied before balance and journal checks');
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000002","role":"authenticated","aal":null}',true);
select throws_ok(format($q$select public.close_franchise_profit_period(%L,'2026-10-01','2026-10-31',%L,%L,'TEST October actual expense reconciliation','TEST362-close')$q$,(select v->>'book_id'from finance362 where k='book'),(select id from public.franchise_finance_rule_versions where franchise_type='STANDARD'and version=1),(select v->>'at'from finance362 where k='cutoff')),'42501','FRANCHISE_CLOSE_DENIED','JSON-null AAL is denied independently of an existing successful key');
select set_config('request.jwt.claims','{"sub":"a3620000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.franchise_operational_missions_v1('a3622000-0000-4000-8000-000000000001')$$,'42501','FRANCHISE_OPERATIONS_SCOPE_DENIED','foreign actor cannot use a library UUID as a mandate');
reset role;
select is((select count(*)::integer from public.franchise_pnl_entries where book_id=(select(v->>'book_id')::uuid from finance362 where k='book')),1,'only one classified net expense was written');
select is((select count(*)::integer from public.franchise_profit_closure_versions where book_id=(select(v->>'book_id')::uuid from finance362 where k='book')),1,'retry and rejected requests created no duplicate closure');
select is((select sum(amount_minor)::text from public.franchise_profit_allocations where closure_version_id=(select(v->>'closure_version_id')::uuid from finance362 where k='close')),'0','a loss allocates zero and never manufactures beneficiary debt');
select is((select count(*)::integer from public.franchise_distribution_ledger_entries where book_id=(select(v->>'book_id')::uuid from finance362 where k='book')),0,'no financial distribution is manufactured for a loss');
select ok((select pg_get_functiondef('public.close_franchise_profit_period(uuid,date,date,uuid,timestamptz,text,text,uuid)'::regprocedure)like'%assert_credit_economic_profit_close_ready_v1%'),'native reconciliation guard remains present after retry repair');
select ok(not has_function_privilege('anon','public.franchise_operational_missions_v1(uuid)','EXECUTE')and not has_function_privilege('service_role','public.franchise_operational_missions_v1(uuid)','EXECUTE'),'purpose-bound mission projection has no anonymous or worker bypass');
select *from finish();
rollback;
